class Solution {
  public int neighborNotesFirstQualifyingSlip(int[] readings, int k) {
    int[] a=readings; List<Integer> out=new ArrayList<>();
    {for(int i=1;i<a.length;i++)out.add(a[i]-a[i-1]);}
    for(int x:out)if(x>=k)return x;return -1;
  }
}
